import { dirname, isAbsolute, join } from 'node:path'
import { createAcpRuntime, resolveExecutable, type AcpAgentProfile, type SpawnFn } from '@vis/workbench-core'
import { deepseekSandbox } from './descriptor'
import { dshOverlay } from './overlay'
import { resolveDsh } from './resolve-dsh'
import { configChoices, modelOption } from './model-options'

export { ACP_PROTOCOL_VERSION, MCP_SERVER } from '@vis/workbench-core'

export type DeepseekRuntimeOptions = {
  spawn?: SpawnFn
  dshPath?: string
  /** Directory containing the vis command generated by studiod, added to the Agent PATH */
  cliBinDir?: string
  /** Packaged tools appended after the user PATH. */
  fallbackDirs?: readonly string[]
  /** Session working directory, also the DSH session cwd; resume must use the same directory */
  workDir(sessionId: string): string
  /** Overlay configuration file location, written by the adapter */
  overlayPath: string
  /** Issue a runtime token; store only its hash in the database */
  issueToken(): { token: string; tokenHash: string }
  socketPath: string
  /** Command to start the vis MCP server; command must be an absolute path */
  visMcp: { command: string; args: string[] }
  dataDir?: string
  forbiddenPaths?: readonly string[]
  model?: string
  /** Maximum wait from startup until session/prompt is sent */
  startTimeoutMs?: number
  /** Rejection within this interval after session/prompt is sent means nonreceipt; after it, assume acceptance */
  admissionMs?: number
  /** Grace period for DSH to exit during interruption or cleanup; stop the process immediately on timeout */
  interruptGraceMs?: number
  env?: Record<string, string | undefined>
  now?: () => number
}

/** dsh supplies launch files, native tool metadata and defaults; ACP lifecycle lives in workbench-core. */
export function createDeepseekRuntime(
  ctx: Parameters<typeof createAcpRuntime>[0],
  opts: DeepseekRuntimeOptions,
): ReturnType<typeof createAcpRuntime> {
  const overlayPath = (sessionId: string) => `${opts.overlayPath}.${sessionId}.yml`
  const profile: AcpAgentProfile = {
    kind: 'deepseek',
    label: 'DeepSeek Harness',
    processLabel: 'dsh',
    sandbox: deepseekSandbox,
    sessionFiles: ({ sessionId, sandbox, skillsPath, work }) => [{ path: overlayPath(sessionId), content: dshOverlay(opts.model, skillsPath, !sandbox.notice, work, sandbox.isolation) }],
    launch: ({ sessionId, sandbox }) => {
      const executable = resolveDsh({ ...(opts.dshPath ? { dshPath: opts.dshPath } : {}), ...(opts.env ? { env: opts.env } : {}) })
      if (!executable) throw new Error('dsh was not found; run npx @deepseek-ai/dsh once, or set VIS_DSH_PATH')
      console.info(`[dsh] ${JSON.stringify(executable)}`)
      const resolved = resolveExecutable('dsh', executable.path, sandbox.env)
      return { command: resolved.command, args: [...resolved.args, '--profile', 'acp', '--patch', overlayPath(sessionId)] }
    },
    instructions: 'launch',
    readOnlyEnforcedByAgent: true,
    config: { model: 'model', effort: 'reasoning_effort' },
    classifyTool: (tool, workDir) => {
      // dsh labels native tools as other; known titles recover approval categories.
      const nativeKind = tool.kind && tool.kind !== 'other' ? tool.kind
        : ['bash', 'pwsh'].includes(tool.title) ? 'execute'
          : ['write', 'edit'].includes(tool.title) ? 'edit'
            : ['web_search', 'web_fetch'].includes(tool.title) ? 'fetch' : tool.kind
      const kind = ['execute', 'edit', 'delete', 'move', 'fetch', 'read'].includes(nativeKind) ? nativeKind as 'execute' | 'edit' | 'delete' | 'move' | 'fetch' | 'read' : 'other'
      const workdir = tool.rawInput?.workdir
      let cwd: string | undefined = workDir
      if (kind === 'execute' && workdir !== undefined) cwd = typeof workdir === 'string' && workdir ? isAbsolute(workdir) ? workdir : `${workDir}/${workdir}` : undefined
      const paths = kind === 'edit' ? toolWritePaths(tool) : undefined
      return { kind, ...(cwd === undefined ? {} : { cwd }), ...(paths ? { paths } : {}),
        ...(kind === 'execute' && tool.rawInput?.sandbox_permissions !== undefined ? { autoApprovalBlocked: true } : {}),
        visTool: typeof tool.title === 'string' && /^mcp__vis__[A-Za-z0-9_]+$/.test(tool.title),
      }
    },
    permissionSummary: 'DeepSeek 请求工具权限',
    itemPrefix: 'ds',
    resume: 'session/resume',
    defaultEffort: option => configChoices(option).some(choice => choice.value === '') ? '' : 'high',
    modelOption,
  }
  return createAcpRuntime(ctx, { ...opts, probeDir: join(dirname(dirname(opts.overlayPath)), 'sessions') }, profile)
}

function toolWritePaths(tool: Record<string, any>): string[] | undefined {
  if (!['write', 'edit'].includes(tool.title) || typeof tool.rawInput?.file_path !== 'string' || !tool.rawInput.file_path.trim()) return
  // ACP locations are descriptive only and cannot prove that an unknown tool's write targets are complete.
  const paths: string[] = [tool.rawInput.file_path]
  if (tool.locations !== undefined) {
    if (!Array.isArray(tool.locations)) return
    for (const location of tool.locations) {
      if (typeof location?.path !== 'string') return
      paths.push(location.path)
    }
  }
  return paths
}
